#include <stdlib.h>
typedef struct{int**p,m,n;}NumMatrix;NumMatrix* numMatrixCreate(int**a,int m,int*cols){NumMatrix*x=malloc(sizeof(*x));x->m=m;x->n=m?cols[0]:0;x->p=malloc((m+1)*sizeof(int*));for(int i=0;i<=m;i++)x->p[i]=calloc(x->n+1,sizeof(int));for(int i=0;i<m;i++)for(int j=0;j<x->n;j++)x->p[i+1][j+1]=a[i][j]+x->p[i][j+1]+x->p[i+1][j]-x->p[i][j];return x;}int numMatrixSumRegion(NumMatrix*x,int r1,int c1,int r2,int c2){return x->p[r2+1][c2+1]-x->p[r1][c2+1]-x->p[r2+1][c1]+x->p[r1][c1];}void numMatrixFree(NumMatrix*x){for(int i=0;i<=x->m;i++)free(x->p[i]);free(x->p);free(x);}
